bool coordinate(double x,double y){return std::isfinite(x)&&std::isfinite(y)&&x>=0&&y>=0&&x<1620&&y<2060;}
int tokenAt(const Geometry& g,double sx,double sy){
 auto m=g->data["transform"].toArray();double a=m[0].toDouble(),b=m[1].toDouble(),c=m[2].toDouble(),d=m[3].toDouble(),x=sx-m[4].toDouble(),y=sy-m[5].toDouble(),det=a*d-b*c;
 double px=(d*x-c*y)/det,py=(-b*x+a*y)/det;if(!std::isfinite(px)||!std::isfinite(py))return -1;auto crop=sourceClip(g->data);if(crop&&!crop->contains(px,py))return -1;
 auto words=g->data["words"].toArray(),chars=g->data["chars"].toArray();
 for(int word=0;word<words.size();++word){auto w=words[word].toArray();for(int k=w[0].toInt();k<w[1].toInt();++k){auto q=chars[k].toObject()["quad"].toArray();double minX=1e10,minY=1e10,maxX=-1e10,maxY=-1e10;for(int i=0;i<8;i+=2){minX=std::min(minX,q[i].toDouble());maxX=std::max(maxX,q[i].toDouble());minY=std::min(minY,q[i+1].toDouble());maxY=std::max(maxY,q[i+1].toDouble());}if(maxX-minX<1e-8||maxY-minY<1e-8||px<minX-1e-6||px>maxX+1e-6||py<minY-1e-6||py>maxY+1e-6)continue;int order[]={0,2,6,4};bool positive=false,negative=false;for(int i=0;i<4;++i){int j=order[i],n=order[(i+1)%4];double cross=(q[n].toDouble()-q[j].toDouble())*(py-q[j+1].toDouble())-(q[n+1].toDouble()-q[j+1].toDouble())*(px-q[j].toDouble());positive|=cross>1e-7;negative|=cross< -1e-7;}if(!(positive&&negative)&&(positive||negative))return word;}}
 return -1;
}
// Same immutable snapshot representation as select(), with range-local limits.
// The qualification word-selection cap in semantic_geometry.cpp is unchanged.
Selection snapshot(const Geometry& g,unsigned first,unsigned last,std::uint64_t generation,int blockBegin=-1,int blockEnd=-1){
 auto words=g->data["words"].toArray(),chars=g->data["chars"].toArray();int begin=words[int(first)].toArray()[0].toInt(),end=words[int(last)].toArray()[1].toInt();if(blockBegin>=0&&blockEnd>blockBegin){begin=blockBegin;end=blockEnd;}auto firstChar=chars[begin].toObject(),lastChar=chars[end-1].toObject();int from=firstChar["offset"].toInt(),to=lastChar["offset"].toInt()+lastChar["text"].toString().size();QString page=g->data["text"].toString(),selected=page.mid(from,to-from);QJsonArray quads;for(int i=begin;i<end;++i)quads.append(chars[i].toObject()["quad"]);
 auto line=g->data["lines"].toArray()[firstChar["line"].toInt()].toArray(),block=g->data["blocks"].toArray()[firstChar["block"].toInt()].toArray();QString paragraph=page.mid(block[0].toInt(),block[1].toInt()-block[0].toInt());QString sentence;int local=from-block[0].toInt(),localEnd=to-block[0].toInt();int start=0;for(int i=0;i<local;++i)if(QStringLiteral(".!?").contains(paragraph[i])&&(i+1==paragraph.size()||paragraph[i+1].isSpace()))start=i+1;for(int i=localEnd;i<paragraph.size();++i)if(QStringLiteral(".!?").contains(paragraph[i])&&(i+1==paragraph.size()||paragraph[i+1].isSpace())){sentence=paragraph.mid(start,i+1-start).trimmed();break;}
 bool paragraphCut=false,pageCut=false;QJsonObject o{{"version",1},{"document",g->data["document"]},{"pageId",g->data["pageId"]},{"page",g->data["page"]},{"text",selected},{"normalized",normalize(selected)},{"word",lexical(selected)},{"tokenRange",QJsonArray{int(first),int(last+1)}},{"characterRange",QJsonArray{begin,end}},{"utf16Range",QJsonArray{from,to}},{"quads",quads},{"transform",g->data["transform"]},{"transformId",g->data["transformId"]},{"transformVersion",g->data["transformVersion"]},{"line",bounded(page.mid(line[0].toInt(),line[1].toInt()-line[0].toInt()),512)},{"sentence",bounded(sentence,512)},{"paragraph",bounded(paragraph,1024,&paragraphCut)},{"pageText",bounded(page,8192,&pageCut)},{"paragraphTruncated",paragraphCut},{"pageTruncated",pageCut}};
 if(firstChar["line"]!=lastChar["line"])o["line"]="";if(firstChar["block"]!=lastChar["block"]){o["paragraph"]="";o["sentence"]="";o["paragraphTruncated"]=false;}o["sentencePolicy"]="terminal-punctuation-heuristic-v1";
 if(g->data.contains("visibleSourceRect")){o["viewId"]=g->data["viewId"];o["visibleSourceRect"]=g->data["visibleSourceRect"];}
 auto key=QJsonDocument(QJsonObject{{"document",o["document"]},{"pageId",o["pageId"]},{"range",o["characterRange"]},{"text",o["text"]},{"quads",o["quads"]},{"transformId",o["transformId"]}}).toJson(QJsonDocument::Compact);o["id"]=QString::fromLatin1(underlay::digest(key).toHex());o["generation"]=QString::number(generation);return std::make_shared<const SelectionSnapshot>(o);
}
